WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_judgement_definition_single_cause_result'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '原因与结果', 'kp-xingce-judgement-definition-single-cause-result', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "定义判断：原因与结果"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定位：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "抓住“由于”、“因为”、“导致”、“造成”等引导词。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、实战排雷"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "如果定义的关键在于“因为 A 导致 B”。选项里如果出现了“为了 B 而去干 A”，这就把因果变成了目的，直接打叉排除！"}]}]}$$ AS jsonb), NULL, '原因与结果的核心考点与解题技巧。', category_node.id, CAST('["判断推理", "原因与结果"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_judgement_definition_single_cause_result", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
